<script>
  import { onMount } from 'svelte'

  let klass
  export { klass as class }

  let region
  let down
  let up

  onMount(() => {
    if (typeof window === 'undefined') return
    region.style.cursor = 'pointer'
  })

  function handleClick(event) {
    const primaryCTA =
      region.querySelector('.PrimaryCTA') || region.querySelector('a, button')

    // Allow other CTA clicks through
    if (event.target.closest('a, button') !== primaryCTA) return

    // Activate Primary CTA
    primaryCTA.click()
  }

  function startCountdown() {
    down = performance.now()
  }

  function endCountdown() {
    up = performance.now()
    if (up - down < 200) region.click()
  }
</script>

<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-noninteractive-tabindex a11y-no-static-element-interactions-->
<div
  class="InteractiveRegion {klass}"
  tabindex="0"
  on:click={handleClick}
  on:pointerdown={startCountdown}
  on:pointereup={endCountdown}
  bind:this={region}
>
  <slot />
</div>
